// Error Trigger payload: execution.{id,error,lastNodeExecuted} + workflow.{id,name}. No card id here.
const e = $json || {};
const ex = e.execution || {};
const wf = e.workflow || {};
const err = ex.error || (e.trigger && e.trigger.error) || {};
const node = String((err.node && err.node.name) || ex.lastNodeExecuted || 'unknown node');
const message = String(err.message || err.description || 'unknown error').replace(/\s+/g, ' ').slice(0, 500);
const flow_name = String(wf.name || '');
const flow_id = String(wf.id || '');
// Loop guard: a failure of this flow or of the coach is only logged (this execution is the log).
const loop = flow_name === 'err.card' || flow_name === 'cap.kanban_coach.handle_error' || flow_id === String($workflow.id);
return [{ json: {
  execution_id: (ex.id !== undefined && ex.id !== null) ? String(ex.id) : '',
  flow_id: flow_id, flow_name: flow_name, node: node, message: message, loop: loop
} }];

// The card is in the failed execution's trigger data: Flow object (normalised) first, else the
// Webhook (query+body) or "From another workflow" input. No card id => not a card flow => stop.
const f = $('Failure').first().json;
const ex = $json || {};
const rd = ((ex.data || {}).resultData || {}).runData || {};
const nodes = (ex.workflowData || {}).nodes || [];
const first = (n) => { try { return rd[n][0].data.main[0][0].json || null; } catch (e) { return null; } };
const has = (o) => !!(o && o.card_id !== undefined && o.card_id !== null && String(o.card_id) !== '' && o.board_id !== undefined && o.board_id !== null && String(o.board_id) !== '');
let src = first('Flow object');
if (!has(src)) {
  src = null;
  for (const n of nodes) {
    if (!/\.(webhook|executeWorkflowTrigger)$/.test(String(n.type || ''))) continue;
    const j = first(n.name);
    if (!j) continue;
    const m = (j.query !== undefined || j.headers !== undefined) ? Object.assign({}, j.body || {}, j.query || {}) : j;
    if (has(m)) { src = m; break; }
  }
}
if (!src) return [];
// The tenant comes from the same place as the card: the failed run's Flow object emits tenant_id
// directly; a raw Webhook trigger carries it on the card's custom fields. ABSENT STAYS ABSENT.
let tenant_id = (src.tenant_id !== undefined && src.tenant_id !== null) ? String(src.tenant_id).trim() : '';
if (!tenant_id && src.data) {
  const tinc = src.data.included || {};
  const titem = src.data.item || {};
  const tname = {};
  (tinc.customFields || []).forEach(cf2 => { tname[String(cf2.id)] = String(cf2.name); });
  (tinc.customFieldValues || []).forEach(v => {
    if (titem.id !== undefined && String(v.cardId) === String(titem.id) && tname[String(v.customFieldId)] === 'keycloak_tenant_id') {
      const t = String(v.content || '').trim();
      if (t) tenant_id = t;
    }
  });
}
const block_text = f.node + ': ' + f.message;
return [{ json: {
  card_id: String(src.card_id), board_id: String(src.board_id),
  list: src.list ? String(src.list) : '', card_type: src.card_type ? String(src.card_type) : '',
  flow_name: f.flow_name, flow_id: f.flow_id, execution_id: f.execution_id, node: f.node, message: f.message,
  block_text: block_text,
  tenant_id: tenant_id,
  comment: '[BLOCKED/flow_error] ' + f.flow_name + ' · ' + f.node + ' · ' + f.message
} }];

// The board's BLOCKED list comes from the project (same source the card flows use: planka_list_ids).
const id = ($json.planka_list_ids || {}).BLOCKED;
if (!id) throw new Error('blocked_list_id: project for board ' + $('Resolve card').first().json.board_id + ' has no BLOCKED list');
return [{ json: { blocked_list_id: String(id) } }];
